	eventID := stringValue(t, result["event_id"], "event_id")
	runID := stringValue(t, result["run_id"], "run_id")
	if result["new_run_created"] != true {
		t.Fatalf("sqlite new_run_created = %#v, want true", result["new_run_created"])
	}
