	bundle := eventPublishCreateEntityTestBundle(t)
	source := semanticview.Wrap(bundle)
	bus, err := newScopedAPITestEventBus(t, sqliteStore, runStartTestEventBusOptions(source))
	if err != nil {
		t.Fatalf("NewEventBusWithOptions: %v", err)
	}
