	defer cancel()
	tick := time.NewTicker(10 * time.Millisecond)
	defer tick.Stop()
	want := 0
	cardinality := 0
	if items, ok := step.Payload["items"].([]any); ok {
		want = len(items)
		cardinality = len(items)
	}
