				case <-ctx.Done():
					logScatterGatherProgress(t, h, step.eventID)
					t.Fatalf("%s exact issuance did not close: %v", step.Event, ctx.Err())
				case <-tick.C:
				}
				continue
			}
			issued = true
		}

