		if err != nil {
			logScatterGatherProgress(t, h, step.eventID)
			t.Fatal(err)
		}
		if deadLetters != 0 {
			logScatterGatherFailures(t, h)
			t.Fatalf("%s durable descendants have %d dead letters", step.Event, deadLetters)
		}
		if observed != want+1 || unsettled != 0 {
			select {
			case <-ctx.Done():
				logScatterGatherProgress(t, h, step.eventID)
