				t.Fatalf("prepare fixture initial lifecycle: %v", err)
			}
			construction3500Command, err := flowactivationfixture.Command(construction3500Ctx, construction3500Instance, construction3500Lifecycle, construction3500At)
			if err != nil {
				t.Fatalf("prepare fixture activation command: %v", err)
			}
			construction3500Committed, err := any(pg).(runtimebus.FlowInstanceActivationCommitOwner).CommitFlowInstanceActivation(construction3500Ctx, construction3500Command)
			if err != nil {
				t.Fatalf("seed workflow instance %q: %v", instance.InstanceID, err)
			}
			if err == nil && !construction3500Committed.Acknowledged {
				t.Fatal("fixture activation was not acknowledged")
			}
			if construction3500Committed.Acknowledged && construction3500Committed.Created {
				if finalizeErr := workflowStore.FinalizeInitialEntryLifecycle(construction3500Ctx, construction3500Committed.Lifecycle); finalizeErr != nil {
					t.Fatalf("finalize fixture initial lifecycle: %v", finalizeErr)
				}
			}
		}
	}

	grandchildSource := eventtest.StaticFlowRoutingSource("child/grandchild", "child/grandchild", grandchildEntityID)
	completion := eventtest.ExistingRunRootIngressWithRoutingSource(
		"11111111-2222-3333-4444-555555555555",
		events.EventType("child/grandchild/micro.done"),
		"cataloge2e",
		"",
		[]byte(`{"entity_id":"`+grandchildEntityID+`"}`),
		0,
		eventBusTestRunID,
		events.EnvelopeForEntityID(events.EventEnvelope{}, grandchildEntityID),
		grandchildSource,
		time.Now().UTC(),
	)
	plan, err := eb.CheckPublishRecipientPlan(ctx, completion)
	if err != nil {
		t.Fatalf("completion preflight: %v", err)
	}
	var childRoute events.DeliveryRoute
	for _, route := range plan.DeliveryRoutes {
		if route.Recipient.LocalID() == "child-relay" {
			childRoute = route
			break
		}
	}
	if childRoute.Recipient.Empty() {
		t.Fatalf("completion routes = %#v, want child-relay", plan.DeliveryRoutes)
	}
	claimNode, claimEvent, claimed := childRoute.ConnectClaim.NodeHandlerOwner()
	if !claimed || claimNode.FlowPath() != "child" || claimNode.NodeID() != "child-relay" || claimEvent != "micro.done" {
		t.Fatalf("completion connect claim = node:%s event:%q admitted:%v, want child/child-relay/micro.done", claimNode.Key(), claimEvent, claimed)
	}
	previewEvent := eventtest.ExistingRunRootIngressWithRoutingSource(
		completion.ID(), "micro.done", "cataloge2e", "", completion.Payload(), 0, eventBusTestRunID,
		events.EnvelopeForTargetRoute(events.EventEnvelope{}, childRoute.Target.Route()), grandchildSource, completion.CreatedAt(),
	)
	if _, err := runtimepipeline.PreviewContractHandlerExecution(
		runtimedelivery.WithRoute(ctx, childRoute), bundle, claimNode, previewEvent,
		persistedEventBusPreviewState(t, ctx, workflowStore, runtimeflowidentity.RouteForInstancePath("child")), nil,
	); err != nil {
		t.Fatalf("preview child completion: %v", err)
	}
	if err := eb.Publish(ctx, completion); err != nil {
		t.Fatalf("Publish: %v", err)
	}
	if err := eb.WaitForQuiescence(ctx); err != nil {
		t.Fatalf("WaitForQuiescence: %v", err)
	}
	child, found, err := workflowStore.Load(ctx, testRunScopedFlowRoute(runtimeflowidentity.RouteForInstancePath("child")))
	if err != nil {
		t.Fatalf("load child instance: %v", err)
	}
	if !found {
		t.Fatal("expected child instance")
	}
	if got := strings.TrimSpace(child.CurrentState); got != "completed" {
		t.Fatalf("child current_state = %q, want completed", got)
	}

	var emitted []string
	rows, err := db.QueryContext(context.Background(), `SELECT event_name FROM events ORDER BY created_at ASC, event_id ASC`)
	if err != nil {
		t.Fatalf("query events: %v", err)
	}
	defer rows.Close()
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			t.Fatalf("scan event: %v", err)
		}
		emitted = append(emitted, strings.TrimSpace(name))
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("iterate events: %v", err)
	}

	root, found, err := workflowStore.Load(ctx, testRunScopedFlowRoute(runtimeflowidentity.RouteForInstancePath(eventBusTestRunID)))
	if err != nil {
		t.Fatalf("load root instance: %v", err)
	}
	if !found {
		t.Fatal("expected root instance")
	}
	if got := strings.TrimSpace(root.CurrentState); got != "done" {
		rows, _ := db.QueryContext(context.Background(), `
			SELECT e.event_name, d.subscriber_id, COALESCE(d.status, ''), COALESCE(d.delivery_target_route::text, '')
			FROM event_deliveries d
			JOIN events e ON e.event_id = d.event_id
			ORDER BY e.created_at, d.subscriber_id, d.delivery_target_route::text
		`)
		deliveries := make([]string, 0)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var eventName, subscriberID, status, target string
				if scanErr := rows.Scan(&eventName, &subscriberID, &status, &target); scanErr == nil {
					deliveries = append(deliveries, eventName+"/"+subscriberID+"="+status+" "+target)
				}
			}
		}
		t.Fatalf("root current_state = %q, want done through declared ancestor connects; events=%v deliveries=%v", got, emitted, deliveries)
	}
	if contains(emitted, "child/step.result") {
		t.Fatalf("events = %v, do not want child/step.result", emitted)
	}
	if contains(emitted, "pipeline.complete") {
		t.Fatalf("events = %v, do not want retired dead output pipeline.complete", emitted)
	}
}

