		"support.replay.ok",
		"support.replay.skip",
		"support.replay.leased",
		"support.replay.drop",
	} {
		storetest.CommitSemanticEventWithRoutes(t, ctx, pg,
			eventtest.PersistedProjection(eventIDs[eventType], events.EventType(eventType), "", "", nil, 0, runID, "", events.EventEnvelope{}, time.Now().Add(time.Duration(index-4)*time.Minute).UTC()),
			[]events.DeliveryRoute{{Recipient: events.MustAgentDeliveryRecipient("test-agent"), AgentIdentity: managerReplayIdentity}},
			runtimepipelineobligation.ScopeSubscribed,
		)
		acknowledgeConformancePipelineEvent(t, ctx, pg.PipelineObligations(), eventIDs[eventType])
	}
	if err := rt.Manager.Shutdown(); err != nil {
		t.Fatalf("retire constructed manager before test replacement: %v", err)
	}
	rt.Manager = runtimemanager.NewAgentManagerWithOptions(rt.Bus, func(cfg runtimeactors.AgentConfig) (runtimemanager.Agent, error) {
		return conformanceManagerReplayAgent{id: cfg.ID}, nil
	}, runtimemanager.AgentManagerOptions{
		ExecutionPosture:   executionposture.Live,
		BaseContext:        ctx,
		SourceArtifactFact: fact,
		SemanticSource:     module.SemanticSource(),
		WorkflowInstances:  rt.Pipeline,
		WorkOwner:          rt.WorkOccurrence(),
		DeliveryStore:      pg,
		SessionResetter:    pg,
		PersistenceRoles:   conformanceManagerPersistenceRoles(pg, rt.Bus, rt.Pipeline), ReceiverExecution: eventreceiver.NormalExecution(),
	}, pg)
	rt.Bus.SetCommittedAgentReadinessFinalizer(runtimebus.CommittedAgentReadinessFinalizerFunc(rt.Manager.FinalizeCommittedAgentReadiness))
	installConformanceRuntimeStartupGrant(t, ctx, pg, rt)
	constructionCtx := runtimeeffects.WithExecutionMode(runtimecorrelation.WithRunID(ctx, runID), executionmode.Live)
	plan, err := rt.Manager.PrepareFlowInstanceActivation(constructionCtx, runtimepipeline.FlowInstanceActivationRequest{
		ContractBundle: module.SemanticSource(), Instance: runtimeflowidentity.Stored(module.SemanticSource(), ".", runID, runID, runID, ""), OccurredAt: time.Now().UTC(),
	})
	if err != nil {
		t.Fatalf("prepare replay root before startup recovery: %v", err)
	}

	committed, err := rt.Bus.CommitFlowInstanceActivation(constructionCtx, plan)
	if err != nil || !committed.Acknowledged || !committed.Created {
		t.Fatalf("stage replay root: acknowledged=%t created=%t err=%v", committed.Acknowledged, committed.Created, err)
	}

	if err := rt.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}

	result, err := pg.ListOperatorRuntimeLogs(ctx, operatorread.OperatorRuntimeLogListOptions{
		Component:         "agent-manager",
		ActionOrEventType: "startup_recovery_manager_replay_aftermath",
		Limit:             10,
	})
	if err != nil {
		t.Fatalf("ListOperatorRuntimeLogs: %v", err)
	}
	logs := result.Logs
	if len(logs) != 0 {
		t.Fatalf("retired manager replay aftermath rows = %d, want 0: %#v", len(logs), logs)
	}
}

