			}
			before := []pipeline.WorkflowInstance{load(0), load(1)}
			arms := [][]joinruntime.Activation{
				a2MultiUntilEntryArms(t, before[0], captured[0]), a2MultiUntilEntryArms(t, before[1], captured[1]),
			}
