				if scenario == 7 {
					route := prepared.DeliveryRoutes[0]
					if len(route.Context.Joins) != 1 || route.Context.Joins[0].Ref.StageEntry() != original[0] {
						t.Fatalf("retry of new output invented a newer arm: %#v", route)
					}
