			sourceDeliveryID, arrivalDeliveryID := deliveryID(trigger.ID(), dispatcher.Key()), deliveryID(outputID, collector.Key())
			for _, witness := range witnesses {
				record, instance := a2SameCommitWitnessState(t, witness)
