func TestTargetedDeclaredKeyAgreementAndConflictExecuteThroughDurableEventBusOnBothStores(t *testing.T) {
	for _, storeCase := range []struct {
		name string
		open func(*testing.T) gateRecoveryStoreCase
	}{
