				"run_id": setup.RunID, "event_name": "portfolio.setup", "idempotency_key": "a2-join-q2",
				"payload": map[string]any{"portfolio_id": "portfolio-one", "period_id": "2026-Q2", "expected_operating_ids": []string{"op-a", "op-b"}},
