			requireServedJSONRPCResult(t, rt.Endpoint, "mailbox.decide", params, &decision)
			if lifecycleStoredSnapshot(t, rt, seed.RunID) != settled {
				t.Fatal("recovered gate duplicate mutated history")
			}
