				ExecutionMode: "live",
				ID:            agent.ID(),
				Identity:      managerAgentIdentity(agent.ID()),
				Subscriptions: []string{"test.intervention"},
			})}, false); err != nil {
				t.Fatalf("spawn intervention agent: %v", err)
			}
