				t.Fatalf("ordinary and compiled consumers were not composed: matched=%v plans=%d emit=%q key=%q", resolved.Matched, len(resolved.Handler.JoinUntilPlans), resolved.Handler.Emit.Event, resolved.HandlerEventKey)
			}
