					}
				}
				final := h.instance()
				if final.CurrentState != "ready" || len(final.TransitionHistory) != 3 {
					t.Fatalf("second entry completion = %q history=%#v", final.CurrentState, final.TransitionHistory)
				}
			})
		}
	}
