func publishManagerNativeDeliveryWithRoot(t *testing.T, ctx context.Context, selected managerNativeDeliveryOwner, event events.Event, routes []events.DeliveryRoute, authority deliverylifecycle.ExecutionAuthority, root *runtimebus.FlowInstanceActivationCommand) {
	t.Helper()
	var err error
	if _, bound := event.PayloadAdmission(); !bound {
		event, err = eventfixture.BindPayload(event)
		if err != nil {
			t.Fatal(err)
		}
	}
	admitted, err := events.AdmitForPublish(event, events.AdmissionOptions{RequirePersistentUUIDIdentity: true})
	if err != nil {
		t.Fatal(err)
	}
	if err := storetest.EnsureRunForAdmittedEvent(ctx, selected, admitted, event.CreatedAt()); err != nil {
		t.Fatal(err)
	}
	ledger, err := events.NewConnectEvaluationLedger(nil)
	if err != nil {
		t.Fatal(err)
	}
	var settlement events.RouteSettlement
	if len(routes) == 0 {
		settlement, err = events.NewNoDeliverySettlement(events.EventWriteNormalPublication, events.NoDeliveryDeclaredConsumerNoPlan, ledger)
	} else {
		settlement, err = events.NewDeliverySettlement(events.EventWriteNormalPublication, ledger)
	}
	if err != nil {
		t.Fatal(err)
	}
	publication, err := selected.PipelineObligations().ClaimPublication(ctx, event.ID())
	if err != nil {
		t.Fatal(err)
	}
	defer func() {
		if err := selected.PipelineObligations().Release(context.WithoutCancel(ctx), publication); err != nil {
			t.Error(err)
		}
	}()
	scope := authoractivity.BundleScope(event.ID(), authority.SourceArtifact().BundleHash())
	catalog, err := selected.RegisterAuthorActivityEventCatalog(scope, []authoractivity.EventDescriptor{{EventType: string(event.Type()), Disposition: authoractivity.StoryDifferent}})
	if err != nil {
		t.Fatal(err)
	}
	defer catalog.Release()
	command := runtimebus.PublicationCommand{Commit: runtimebus.CommitPublishRequest{Event: admitted, RouteSettlement: settlement, DeliveryRoutes: routes, DeliveryAuthority: authority, ReplayScope: pipelineobligation.ScopeSubscribed, PipelineClaim: publication}, AuthorScope: scope, HasAuthorScope: true, AuthorDescriptor: authoractivity.EventDescriptor{EventType: string(event.Type()), Disposition: authoractivity.StoryDifferent}, HasAuthorDescriptor: true}
	if root != nil {
		command.Activations = []pipeline.FlowInstanceActivationPlan{root.Plan}
		command.RouteTopology = root.RouteTopology
	}
	committed, err := selected.CommitPublication(ctx, command)
	if err != nil || !committed.Acknowledged {
		t.Fatalf("native publication was not acknowledged: %+v,error=%v", committed, err)
	}
}

